<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {Activity,Play,Plus,RadioTower,RefreshCw,Server,Wifi} from 'lucide-vue-next';import {createCredential,deleteCredential,listCredentials,type Credential} from '@/api/cmdb'
import {useAuthStore} from '@/stores/useAuthStore';import {agentStatusLabel,taskProgress} from '@/features/discovery/discoveryModel'
type Agent={id:string;name:string;hostname:string;ip:string;os?:string;region?:string;status:string;version:string;lastHeartbeat:string};type Item={id:string;name:string;ip:string;state:string};type Task={id:string;name:string;scope:string;status:string;discovered:number;imported:number;items?:Item[]};type Summary={total:number;online:number;tasks:number;pending:number}
const auth=useAuthStore(),agents=ref<Agent[]>([]),tasks=ref<Task[]>([]),summary=ref<Summary>(),busy=ref(false),error=ref('');const agentQuery=ref(''),agentStatus=ref(''),selectedAgent=ref<Agent|null>(null),agentAsset=ref<any|null>(null);const filteredAgents=computed(()=>{const q=agentQuery.value.trim().toLowerCase();return agents.value.filter(a=>{if(agentStatus.value&&a.status!==agentStatus.value)return false;if(q&&!(a.name+' '+a.hostname+' '+a.ip+' '+(a.os||'')).toLowerCase().includes(q))return false;return true})});const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}));async function request<T>(url:string,options?:RequestInit){const r=await fetch(url,{...options,headers:headers.value});if(!r.ok)throw new Error(`请求失败 (${r.status})`);return r.json() as Promise<T>};async function load(){busy.value=true;error.value='';try{[summary.value,agents.value,tasks.value]=await Promise.all([request<Summary>('/api/v1/discovery/summary'),request<Agent[]>('/api/v1/discovery/agents'),request<Task[]>('/api/v1/discovery/tasks')])}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{busy.value=false}};async function openAgent(a:Agent){selectedAgent.value=a;agentAsset.value=null;try{agentAsset.value=await request<any>('/api/v1/cmdb/assets/'+encodeURIComponent(a.id))}catch{agentAsset.value=null}}
function closeAgent(){selectedAgent.value=null;agentAsset.value=null}
async function createTask(){await request<Task>('/api/v1/discovery/tasks',{method:'POST',body:JSON.stringify({name:`网段扫描 ${tasks.value.length+1}`,source:'network',scope:'10.20.0.0/24'})});await load()};async function action(task:Task,type:'run'|'reconcile'){await request<Task>(`/api/v1/discovery/tasks/${task.id}/${type}`,{method:'POST'});await load()};const cidrText=ref('172.28.68.0/24\n172.28.69.0/24');const scanType=ref('physical-server');const scanning=ref(false);const scanResult=ref<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}|null>(null)
async function scanNodeExporter(){scanning.value=true;error.value='';try{const cidrs=cidrText.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);scanResult.value=await request<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}>('/api/v1/discovery/scan-node-exporter',{method:'POST',body:JSON.stringify({cidrs,defaultType:scanType.value,port:9100})});await load()}catch(e){error.value=e instanceof Error?e.message:'扫描失败'}finally{scanning.value=false}}
const sshCidrs=ref('172.28.69.161/32');const sshScanType=ref('');const sshScanning=ref(false);const sshResult=ref<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}|null>(null)
async function scanSSH(){sshScanning.value=true;error.value='';try{const cidrs=sshCidrs.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);sshResult.value=await request<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}>('/api/v1/discovery/scan-ssh',{method:'POST',body:JSON.stringify({cidrs,defaultType:sshScanType.value,port:22,credentialId:sshCred.value})});await load()}catch(e){error.value=e instanceof Error?e.message:'SSH 扫描失败'}finally{sshScanning.value=false}}
const aiHosts=ref('172.28.68.56');const aiType=ref('');const aiGateway=ref('http://172.28.69.161:30080');const aiVersion=ref('');const aiBusy=ref(false);const aiResult=ref<Array<{host:string;ok:boolean;info:string}>>([])
async function batchUninstall(){aiBusy.value=true;error.value='';try{const hosts=aiHosts.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);aiResult.value=await request<Array<{host:string;ok:boolean;info:string}>>('/api/v1/discovery/agent-uninstall',{method:'POST',body:JSON.stringify({hosts,port:22})})}catch(e){error.value=e instanceof Error?e.message:'批量卸载失败'}finally{aiBusy.value=false}}
async function batchInstall(){aiBusy.value=true;error.value='';try{const hosts=aiHosts.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);aiResult.value=await request<Array<{host:string;ok:boolean;info:string}>>('/api/v1/discovery/agent-install',{method:'POST',body:JSON.stringify({hosts,assetType:aiType.value,port:22,gatewayUrl:aiGateway.value,credentialId:aiCred.value})})}catch(e){error.value=e instanceof Error?e.message:'批量安装失败'}finally{aiBusy.value=false}}
const creds=ref<Credential[]>([]);const showCreds=ref(false);const credName=ref('');const credKind=ref('snmp');const credUser=ref('');const credSecret=ref('');const sshCred=ref('');const snmpCred=ref('');const aiCred=ref('');async function loadCreds(){try{creds.value=await listCredentials(auth.token)}catch{creds.value=[]}}async function addCred(){try{await createCredential(auth.token,{name:credName.value,kind:credKind.value,username:credUser.value,secret:credSecret.value});credName.value='';credUser.value='';credSecret.value='';await loadCreds()}catch(e){error.value=e instanceof Error?e.message:'凭据保存失败'}}async function removeCred(id:string){try{await deleteCredential(auth.token,id);await loadCreds()}catch(e){error.value=e instanceof Error?e.message:'凭据删除失败'}}
const snmpCidrs=ref('172.31.42.124/32');const snmpType=ref('');const snmpBusy=ref(false);const snmpResult=ref<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}|null>(null)
async function scanSNMP(){snmpBusy.value=true;error.value='';try{const cidrs=snmpCidrs.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);snmpResult.value=await request<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}>('/api/v1/discovery/scan-snmp',{method:'POST',body:JSON.stringify({cidrs,defaultType:snmpType.value,credentialId:snmpCred.value})})}catch(e){error.value=e instanceof Error?e.message:'SNMP 扫描失败'}finally{snmpBusy.value=false}}
onMounted(load)
loadCreds();request<{version:string}>('/api/v1/agent/install/version').then((v)=>aiVersion.value=v.version).catch(()=>{})
</script>
<template><section class="discovery-page"><header class="discovery-heading"><div><span>AGENT & AUTO DISCOVERY</span><h1>Agent 与自动发现</h1><button @click="showCreds=true">凭据管理</button><p>统一管理采集端在线状态、发现任务与 CMDB 数据入库。</p></div></header><div v-if="error" class="discovery-error">{{error}}</div><div class="discovery-summary"><article><RadioTower/><div><span>Agent 总数</span><strong>{{summary?.total??0}}</strong></div></article><article><Wifi/><div><span>在线 Agent</span><strong>{{summary?.online??0}}</strong></div></article><article><Activity/><div><span>待纳管资产</span><strong>{{summary?.pending??0}}</strong></div></article><article><Server/><div><span>发现任务</span><strong>{{summary?.tasks??0}}</strong></div></article></div><div class="discovery-grid"><section class="discovery-panel"><header><div><h2>采集端状态</h2><span>实时心跳与版本</span></div><button @click="load"><RefreshCw :class="{spin:busy}"/></button></header><div class="agent-toolbar"><input v-model="agentQuery" placeholder="搜索主机名/IP/OS"><select v-model="agentStatus"><option value="">全部状态</option><option value="online">在线</option><option value="offline">离线</option></select></div>
        <div class="agent-list"><article v-for="agent in filteredAgents" :key="agent.id" @click="openAgent(agent)" class="agent-row"><i :data-status="agent.status"></i><div><strong>{{agent.name}}</strong><span>{{agent.ip}} · {{agent.hostname}} · {{agent.os||'未知OS'}} · v{{agent.version}}</span></div><b :data-status="agent.status">{{agentStatusLabel(agent.status)}}</b><time>{{agent.lastHeartbeat||'尚未连接'}}</time></article></div></section><section class="discovery-panel tasks"><header><div><h2>发现任务</h2><span>扫描、识别并纳管基础设施</span></div></header><article v-for="task in tasks" :key="task.id" class="task-card"><div class="task-title"><div><strong>{{task.name}}</strong><span>{{task.scope}}</span></div><b>{{task.status}}</b></div><div class="task-counts"><span>已发现 <strong>{{task.discovered}}</strong></span><span>已入库 <strong>{{task.imported}}</strong></span><span>纳管率 <strong>{{taskProgress(task)}}%</strong></span></div><div class="task-progress"><i :style="{width:taskProgress(task)+'%'}"></i></div><div v-if="task.items?.length" class="discovered-items"><span v-for="item in task.items" :key="item.id"><Server/>{{item.name}}<small>{{item.ip}}</small><b>{{item.state==='imported'?'已入库':'待入库'}}</b></span></div><footer></footer></article></section><section class="discovery-panel scanner"><header><div><h2>node_exporter 网段扫描</h2><span>输入网段探测 9100，发现主机即自动纳管到 CMDB</span></div></header><div class="scanner-form"><label><span>网段（每行一个）</span><textarea v-model="cidrText" rows="3"></textarea></label><label><span>资产类型</span><select v-model="scanType"><option value="">自动识别（默认物理机）</option><option value="physical-server">物理服务器</option><option value="virtual-machine">虚拟机</option></select></label><button class="primary" :disabled="scanning" @click="scanNodeExporter">{{scanning?'扫描中...':'开始扫描并纳管'}}</button></div><div v-if="scanResult" class="scanner-result">扫描 {{scanResult.scanned}} 台 · 发现 node_exporter {{scanResult.found}} 台 · 新纳管 {{scanResult.adopted}} · 合并刷新 {{scanResult.merged}} · 重复/冲突 {{scanResult.conflicts}}</div></section><section class="discovery-panel ssh-scanner"><header><div><h2>SSH 采集</h2><span>对无法安装 Agent 的主机，通过 SSH 采集并入 CMDB（凭据在服务端 Secret 配置）</span></div></header><div class="scanner-form"><label><span>主机/网段（每行一个）</span><textarea v-model="sshCidrs" rows="3"></textarea></label><label><span>资产类型</span><select v-model="sshScanType"><option value="">自动识别（默认物理机）</option><option value="physical-server">物理服务器</option><option value="virtual-machine">虚拟机</option></select></label><label><span>凭据</span><select v-model="sshCred"><option value="">使用服务端默认</option><option v-for="c in creds.filter(x=>x.kind==='ssh')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="primary" :disabled="sshScanning" @click="scanSSH">{{sshScanning?'采集并纳管中...':'SSH 采集并纳管'}}</button></div><div v-if="sshResult" class="scanner-result">扫描 {{sshResult.scanned}} · 发现 {{sshResult.found}} · 新纳管 {{sshResult.adopted}} · 合并刷新(按IP去重) {{sshResult.merged}} · 重复/冲突 {{sshResult.conflicts}}</div></section><section class="discovery-panel agent-install"><header><div><h2>Agent 批量安装</h2><span>通过 SSH 在目标主机安装并启动 cmdb-agent（二进制由服务端 CMDB_AGENT_BUNDLE_URL 下发）</span></div></header><div class="scanner-form"><label><span>主机 IP（每行一个）</span><textarea v-model="aiHosts" rows="3"></textarea></label><label><span>网关地址(安装源)</span><input v-model="aiGateway" placeholder="http://节点IP:30080"></label><label><span>资产类型</span><select v-model="aiType"><option value="">自动识别（默认物理机）</option><option value="physical-server">物理服务器</option><option value="virtual-machine">虚拟机</option></select></label><label><span>凭据</span><select v-model="aiCred"><option value="">使用服务端默认</option><option v-for="c in creds.filter(x=>x.kind==='ssh')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="primary" :disabled="aiBusy" @click="batchInstall">{{aiBusy?'安装/升级中...':`批量安装/升级 Agent${aiVersion?(' (v'+aiVersion+')'):''}`}}</button>
          <button class="primary danger" :disabled="aiBusy" @click="batchUninstall">批量卸载 Agent</button></div><div class="ai-results"><p v-for="r in aiResult" :key="r.host" :class="{ok:r.ok}">{{r.host}} → {{r.ok?'成功':'失败'}} · {{r.info}}</p></div></section><div v-if="selectedAgent" class="modal-backdrop"><section class="agent-detail"><header><div><span>AGENT DETAIL</span><h2>{{selectedAgent.name || selectedAgent.hostname}}</h2></div><button @click="closeAgent">✕</button></header><dl><dt>Agent ID</dt><dd>{{selectedAgent.id}}</dd><dt>主机名</dt><dd>{{selectedAgent.hostname}}</dd><dt>IP</dt><dd>{{selectedAgent.ip}}</dd><dt>操作系统</dt><dd>{{selectedAgent.os||'-'}}</dd><dt>区域</dt><dd>{{selectedAgent.region||'-'}}</dd><dt>版本</dt><dd>v{{selectedAgent.version}}</dd><dt>状态</dt><dd>{{selectedAgent.status}}</dd><dt>最近心跳</dt><dd>{{selectedAgent.lastHeartbeat}}</dd><template v-if="agentAsset"><dt>CMDB 类型</dt><dd>{{agentAsset.typeName}}</dd><dt>负责人</dt><dd>{{agentAsset.owner}}</dd><dt>项目组</dt><dd>{{agentAsset.projectGroup}}</dd></template></dl></section></div><section class="discovery-panel snmp-scanner"><header><div><h2>SNMP 网络设备采集</h2><span>扫描网络设备的只读 community（服务端配置），发现即纳管为 network-device</span></div></header><div class="scanner-form"><label><span>网段（每行一个）</span><textarea v-model="snmpCidrs" rows="3"></textarea></label><label><span>资产类型</span><select v-model="snmpType"><option value="">自动识别(网络设备/带外服务器)</option><option value="network-device">网络设备</option><option value="physical-server">服务器(带外)</option></select></label><label><span>凭据</span><select v-model="snmpCred"><option value="">使用服务端默认</option><option v-for="c in creds.filter(x=>x.kind==='snmp')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="primary" :disabled="snmpBusy" @click="scanSNMP">{{snmpBusy?'扫描中...':'SNMP 扫描并纳管'}}</button></div><div v-if="snmpResult" class="scanner-result">扫描 {{snmpResult.scanned}} · 发现设备 {{snmpResult.found}} · 新纳管 {{snmpResult.adopted}} · 合并 {{snmpResult.merged}} · 冲突 {{snmpResult.conflicts}}</div></section><div v-if="showCreds" class="modal-backdrop"><section class="asset-editor"><header><div><span>VAULT CREDENTIALS</span><h2>凭据管理</h2></div><button @click="showCreds=false">✕</button></header><div class="editor-grid"><label><span>名称</span><input v-model="credName"></label><label><span>类型</span><select v-model="credKind"><option value="ssh">SSH</option><option value="snmp">SNMP</option></select></label><label><span>用户名</span><input v-model="credUser"></label><label><span>密码/Community</span><input v-model="credSecret" type="password"></label></div><footer><button @click="showCreds=false">关闭</button><button class="primary" @click="addCred">保存到 Vault</button></footer><ul><li v-for="c in creds" :key="c.id">{{c.kind}} · {{c.name}} ({{c.username||'-'}}) <button @click="removeCred(c.id)">删除</button></li></ul></section></div></div></section></template>

